  async function exportExcel(filename,headers,rows){const logo=await brandLogoData(),cols=Math.max(1,headers.length),html=`<html dir="rtl"><head><meta charset="utf-8"><style>body{font-family:Arial}table{border-collapse:collapse;width:100%}td,th{border:1px solid #cbd5e1;padding:8px;text-align:right}th{background:#eef3f8}.excel-brand{text-align:center;border:0}.excel-brand img{width:72px;height:72px;object-fit:contain}.excel-title{font-size:19px;font-weight:700}</style></head><body><table><tr><td class="excel-brand" colspan="${cols}">${logo?`<img src="${logo}">`:''}<div class="excel-title">${esc(db.company.name||'الميزان برو')}</div><div>${esc(db.company.legalName||'')}</div><div>${esc(db.company.phone||'')} — ${esc(db.company.address||'')}</div></td></tr><tr><th colspan="${cols}">${esc(filename)}</th></tr><thead><tr>${headers.map(h=>`<th>${esc(h)}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${r.map(c=>`<td>${esc(c)}</td>`).join('')}</tr>`).join('')}</tbody></table></body></html>`;downloadBlob(filename+'.xls',html,'application/vnd.ms-excel;charset=utf-8');toast('تم تجهيز ملف Excel')}

function tableExportData(btn){
  const block=btn.closest('.data-table-block'),tableEl=block?.querySelector('table');
  if(!block||!tableEl)throw Error('تعذر قراءة السجل.');
  const ths=$$('thead th',tableEl),keep=[];
  ths.forEach((th,i)=>{
    const label=(th.textContent||'').replace(/\s+/g,' ').trim();
    if(/^(الإجراءات|إجراء|تحميل|تصدير)$/i.test(label))return;
    keep.push({i,label:label||`حقل ${i+1}`})
  });
  const rows=$$('tbody tr',tableEl).map(tr=>{
    const tds=$$(':scope > td',tr);
    return keep.map(({i})=>{
      const td=tds[i];if(!td)return '';
      const input=td.querySelector('input:not([type=hidden])'),select=td.querySelector('select'),textarea=td.querySelector('textarea');
      if(select)return select.options[select.selectedIndex]?.textContent?.trim()||'';
      if(input)return input.value||'';
      if(textarea)return textarea.value||'';
      const clone=td.cloneNode(true);
      clone.querySelectorAll('button,svg,.table-actions,.icon-button').forEach(x=>x.remove());
      return (clone.textContent||'').replace(/\s+/g,' ').trim()
    })
  });
  const modalTitle=block.closest('.modal')?.querySelector('.modal-head h3')?.textContent;
  const pageTitle=$('.page-head h1')?.textContent||$('#pageTitle')?.textContent||PAGE_META[state.view]?.[0];
  const title=String(modalTitle||pageTitle||'سجل').trim();
  return {title,headers:keep.map(x=>x.label),rows,company:{name:db.company.name||'الميزان برو',legalName:db.company.legalName||'',phone:db.company.phone||'',address:db.company.address||'',taxNumber:db.company.taxNumber||''},createdAt:now()}
}
  async function brandLogoData(){return 'data:image/png;base64,'}

async function exportTableExcel(btn){
  try{
    const r=tableExportData(btn);
    await exportExcel(r.title,r.headers,r.rows);
  }catch(e){toast(e.message||'تعذر تصدير Excel','error')}
}

async function exportTablePDF(btn){
  try{
    const r=tableExportData(btn),logo=await brandLogoData(),w=window.open('','_blank');
    if(!w)throw Error('اسمح بفتح النوافذ لتنزيل PDF.');
    const rows=r.rows.map(row=>`<tr>${row.map(v=>`<td>${esc(v)}</td>`).join('')}</tr>`).join('');
    w.document.open();
    w.document.write(`<!doctype html><html dir="rtl" lang="ar"><head><meta charset="utf-8"><title>${esc(r.title)}</title><style>@page{size:A4 landscape;margin:12mm}*{box-sizing:border-box}body{font-family:Tahoma,Arial,sans-serif;color:#172033;margin:0}.brand{text-align:center;border-bottom:2px solid #1f4b7a;padding-bottom:12px;margin-bottom:14px}.brand img{width:72px;height:72px;object-fit:contain}.brand h1{margin:5px 0 2px;font-size:20px}.brand p{margin:2px;color:#64748b;font-size:11px}.report-title{display:flex;justify-content:space-between;align-items:center;margin:10px 0}.report-title h2{font-size:17px;margin:0}.report-title span{font-size:10px;color:#64748b}table{border-collapse:collapse;width:100%;font-size:10px;table-layout:auto}th,td{border:1px solid #cbd5e1;padding:6px;text-align:right;vertical-align:top;word-break:break-word}th{background:#eef3f8;font-weight:700}tbody tr:nth-child(even){background:#f8fafc}.footer{margin-top:12px;font-size:9px;color:#64748b;text-align:center}</style></head><body><header class="brand">${logo?`<img src="${logo}" alt="">`:''}<h1>${esc(r.company.name)}</h1>${r.company.legalName?`<p>${esc(r.company.legalName)}</p>`:''}<p>${esc(r.company.phone)} ${r.company.address?' — '+esc(r.company.address):''}${r.company.taxNumber?' — الرقم الضريبي: '+esc(r.company.taxNumber):''}</p></header><div class="report-title"><h2>${esc(r.title)}</h2><span>${r.rows.length} سجل — ${new Date(r.createdAt).toLocaleString('ar-EG')}</span></div><table><thead><tr>${r.headers.map(h=>`<th>${esc(h)}</th>`).join('')}</tr></thead><tbody>${rows}</tbody></table><div class="footer">${esc(r.company.name)} — نظام الميزان برو</div><script>window.onload=()=>setTimeout(()=>window.print(),250)<\/script></body></html>`);
    w.document.close();
  }catch(e){toast(e.message||'تعذر تجهيز PDF','error')}
}
  function parseCSV(text){const rows=[];let row=[],cell='',quoted=false;for(let i=0;i<text.length;i++){const c=text[i],n=text[i+1];if(c==='"'&&quoted&&n==='"'){cell+='"';i++}else if(c==='"'){quoted=!quoted}else if(c===','&&!quoted){row.push(cell.trim());cell=''}else if((c==='\n'||c==='\r')&&!quoted){if(c==='\r'&&n==='\n')i++;row.push(cell.trim());if(row.some(Boolean))rows.push(row);row=[];cell=''}else cell+=c}if(cell||row.length){row.push(cell.trim());rows.push(row)}return rows}
